preConditionHook:
// The swing-extreme breakout that fails. Long: this bar's low trades below
// the most recent confirmed swing low but the bar CLOSES back above it. Short
// is the mirror at a swing high.
//
// THE PIVOT SCAN IS INLINED from rules/SwingHigh.json, the corpus's measured
// primitive, exactly as the B-list decision says to (inline it; do not
// reference the rule file). It reproduces EasyLanguage's
// SwingHighBar/SwingLowBar, and the twin reads the same pivot as a PRICE
// through SwingHigh/SwingLow. Measured, EL_Swing_Probe.txt:
//
//   * THE PIVOT TEST IS MIXED: the pivot bar is STRICTLY beyond the
//     `strength` NEWER bars and AT OR BEYOND the `strength` OLDER ones, so a
//     flat top yields exactly one pivot, the LATER of the equal bars. Hence
//     el_gt on the newer side and el_ge on the older side.
//   * CONFIRMATION LAG is exactly `strength` bars -- no lookahead.
//   * THE -1 SENTINEL is real and is guarded below: -1 as a PRICE sits under
//     every real price, so an unguarded read fires the long side on warm-up.
//   * `lookback` is EL's Length: candidate offsets 0..lookback-1, and the
//     neighbourhood test reaches `strength` bars PAST the window, so the
//     deepest bar touched is lookback - 1 + strength.
//   * The comparisons carry the 2.22e-12 relational tolerance, so the scan
//     uses el_gt / el_ge and not raw > and >=.
//
// THE PIVOT IS READ AT THE CURRENT BAR, NOT LAGGED. The newest pivot the scan
// can return sits `strength` bars back, and to be a pivot low that bar must
// be STRICTLY below the `strength` bars newer than it -- bar 0 among them --
// so el_lt(low[0], pivot) can never hold against a pivot confirmed on this
// bar. The rule therefore cannot fire against a pivot that has not yet been
// broken, which is what the merged pseudocode's [1] was reaching for, and the
// twin avoids the unmeasured lagged function read SwingLow(...)[1].
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivStrength = (int)strength;
pivWindow = (int)lookback;
pivotHighBar = -1;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool ok = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivStrength; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) { pivotHighBar = j; break; }
}
pivotLowBar = -1;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool ok = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivStrength; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) { pivotLowBar = j; break; }
}
failLow = false;
failHigh = false;
if (pivotLowBar != -1) {
    failLow = el_lt(low[0], low[pivotLowBar]) && el_gt(close[0], low[pivotLowBar]);
}
if (pivotHighBar != -1) {
    failHigh = el_gt(high[0], high[pivotHighBar]) && el_lt(close[0], high[pivotHighBar]);
}
